72			cancelButton.style.cursor = 'pointer';
73			cancelButton.style.fontWeight = 'bold';
74	
75			const closeModal = () => {
76				document.body.removeChild(modalOverlay);
77			};
78	
79			confirmButton.addEventListener('click', () => {
80				closeModal();
81				resolve(true);
82			});
83	
84			cancelButton.addEventListener('click', () => {
85				closeModal();
86				resolve(false);
