200	function isValidURL(url) {
201		if(url.includes('&'))
202			return false;
203	
204		const http_pattern = /^(https?|ftp):\/\/[^\s$?#]+$/;
205		const ssh_pattern = /^(.+@|ssh:\/\/).+:.+$/;
206		return http_pattern.test(url) || ssh_pattern.test(url);
207	}
