350	export async function fetchData(route, options) {
351		let err;
352		const res = await api.fetchApi(route, options).catch(e => {
353			err = e;
354		});
355	
356		if (!res) {
357			return {
358				status: 400,
359				error: new Error("Unknown Error")
360			}
361		}
362	
363		const { status, statusText } = res;
364		if (err) {
365			return {
366				status,
367				error: err
368			}
369		}
370	
371		if (status !== 200) {
372			return {
373				status,
374				error: new Error(statusText || "Unknown Error")
375			}
376		}
377	
378		const data = await res.json();
379		if (!data) {
380			return {
381				status,
382				error: new Error(`Failed to load data: ${route}`)
383			}
384		}
385		return {
386			status,
387			data
388		}
389	}
