493	export function getTimeAgo(dateStr) {
494		const date = new Date(dateStr);
495	
496		if (!date || !(date instanceof Date) || isNaN(date.getTime())) {
497			return "";
498		}
499	
500		const units = [
501			{ max: 2760000, value: 60000, name: 'minute', past: 'a minute ago', future: 'in a minute' },
502			{ max: 72000000, value: 3600000, name: 'hour', past: 'an hour ago', future: 'in an hour' },
503			{ max: 518400000, value: 86400000, name: 'day', past: 'yesterday', future: 'tomorrow' },
504			{ max: 2419200000, value: 604800000, name: 'week', past: 'last week', future: 'in a week' },
505			{ max: 28512000000, value: 2592000000, name: 'month', past: 'last month', future: 'in a month' }
506		];
507	    const diff = Date.now() - date.getTime();
508	    // less than a minute
509	    if (Math.abs(diff) < 60000)
510	        return 'just now';
511	    for (let i = 0; i < units.length; i++) {
512	        if (Math.abs(diff) < units[i].max) {
513	            return format(diff, units[i].value, units[i].name, units[i].past, units[i].future, diff < 0);
514	        }
515	    }
516	    function format(diff, divisor, unit, past, future, isInTheFuture) {
517			const val = Math.round(Math.abs(diff) / divisor);
518			if (isInTheFuture)
519				return val <= 1 ? future : 'in ' + val + ' ' + unit + 's';
520			return val <= 1 ? past : val + ' ' + unit + 's ago';
521		}
522	    return format(diff, 31536000000, 'year', 'last year', 'in a year', diff < 0);
523	};
